```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int n;
    while (plik >> n) tab.push_back(n);

    int ile = 0;
    cout << "a) Pary o sumie podzielnej przez 10:" << endl;
    for (int i = 0; i < (int)tab.size(); i++) {
        for (int j = i + 1; j < (int)tab.size(); j++) {
            int suma = tab[i] + tab[j];
            if (suma % 10 == 0) {
                cout << "   (" << i << "," << j << "): " << tab[i] << "+" << tab[j] << "=" << suma << endl;
                ile++;
            }
        }
    }
    cout << "b) Znaleziono: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Podwojna petla z warunkiem j > i generuje wszystkie pary bez powtorzen. Sprawdzamy podzielnosc sumy przez 10.

Weryfikacja (dane: [0]=13, [1]=27, [2]=45, [3]=35, [4]=72, [5]=18, [6]=55, [7]=63):
